```java
import java.lang.reflect.*;

Class<?> clazz = User.class;

// All fields, including private ones
for (Field f : clazz.getDeclaredFields()) {
    System.out.println(f.getType() + " " + f.getName());
}

// All methods including inherited public ones
for (Method m : clazz.getMethods()) {
    System.out.println(m.getReturnType() + " " + m.getName());
}

// Annotations on the class
for (Annotation a : clazz.getAnnotations()) {
    System.out.println(a);
}

// Instantiate via no-arg constructor
User u = (User) clazz.getDeclaredConstructor().newInstance();

// Invoke a method by name
Method m = clazz.getMethod("setName", String.class);
m.invoke(u, "Alice");
```

Note the distinction: `getFields()` returns **public** fields including inherited; `getDeclaredFields()` returns all fields declared **on this class** including private but not inherited. Same for methods.

```java
// 1. Inspect class structure
Class<?> c = User.class;
for (Field f : c.getDeclaredFields()) {
    System.out.println(f.getType() + " " + f.getName());
}
for (Method m : c.getDeclaredMethods()) {
    System.out.println(Modifier.toString(m.getModifiers()) + " " + m.getName());
}

// 2. Read/write private field (requires setAccessible(true))
Field name = User.class.getDeclaredField("name");
name.setAccessible(true);
User u = new User();
name.set(u, "Alice");
String n = (String) name.get(u);

// 3. Invoke a method dynamically
Method m = User.class.getDeclaredMethod("greet", String.class);
m.setAccessible(true);
String result = (String) m.invoke(u, "Bob");

// 4. Call constructor with args
Constructor<User> ctor = User.class.getDeclaredConstructor(String.class, int.class);
User u2 = ctor.newInstance("Alice", 30);

// 5. Find fields annotated with @Inject (framework pattern)
for (Field f : c.getDeclaredFields()) {
    if (f.isAnnotationPresent(Inject.class)) {
        f.setAccessible(true);
        f.set(target, resolveDependency(f.getType()));   // DI
    }
}

// 6. MethodHandle — faster alternative for hot paths
import java.lang.invoke.*;

MethodHandles.Lookup lookup = MethodHandles.lookup();
MethodHandle greet = lookup.findVirtual(User.class, "greet",
    MethodType.methodType(String.class, String.class));
String out = (String) greet.invoke(u, "Bob");
// MethodHandle: ~2-3x faster than Method.invoke on JIT-hot paths

