import javax.lang.model.SourceVersion;
import javax.lang.model.element.TypeElement;
import java.util.Set;

@SupportedAnnotationTypes("com.example.GenerateToString")
@SupportedSourceVersion(SourceVersion.RELEASE_17)
public class GenerateToStringProcessor extends AbstractProcessor {
    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment env) {
        for (var element : env.getElementsAnnotatedWith(GenerateToString.class)) {
            // Generate a new Java source file using JavaPoet or raw printwriter
            // processingEnv.getFiler().createSourceFile(...)
        }
        return true;
    }
